{
  "packet_id": "H6-T03-2",
  "claim_id": "C026",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C026.component",
    "value": "Supported timing showing that an identified approval occurred only after placement can establish that this approval was late.",
    "scope": "The identified approval only; conditional on supported timing and does not rule out another earlier approval.",
    "provenance": {
      "refs": [
        {
          "source_id": "P020",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the timing-to-lateness inference and its explicit limitation concerning possible earlier approval."
    }
  },
  "signal_basis": {
    "component_id": "C026.signal_basis",
    "value": "Cross-checked order and approval dates establish that the identified approval itself occurred after placement, distinguishing its occurrence from documentation creation or upload.",
    "scope": "The particular order and identified approval; the proposed timing finding is assumed to occur for this assessment. An upload timestamp or later account alone does not establish approval timing.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
